<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { Plus, Pencil, Users, Cpu, SlidersHorizontal, Sparkles, RefreshCw, ShieldCheck, KeyRound } from 'lucide-vue-next'
import { api, auth, labels, time, type Row } from '../api'
import { useAction, useEditor } from '../forms'
import type { Field } from '../components/FormModal.vue'
import FormModal from '../components/FormModal.vue'
import StatusBadge from '../components/StatusBadge.vue'
const settings=ref<Row|null>(null),users=ref<Row[]>([]),error=ref(''),monitorResult=ref<Row|null>(null)
async function load() {try{[settings.value,users.value]=await Promise.all([api('/workspace/settings'),api<Row[]>('/users')]);error.value=''}catch(err){error.value=(err as Error).message}}
const editor=useEditor(load),action=useAction(load)
const roleOptions=[{value:'admin',label:'管理员'},{value:'operator',label:'运营人员'},{value:'viewer',label:'查看人员'}]
function createUser() {editor.open('创建用户',[{key:'username',label:'用户名',required:true,hint:'至少 3 位，使用英文、数字、下划线或点。'},{key:'display_name',label:'显示名称',required:true},{key:'password',label:'初始密码',type:'password',required:true,hint:'至少 8 位。'},{key:'role',label:'角色',type:'select',options:roleOptions,required:true}],{role:'viewer'},'/users')}
function editUser(user:Row) {const fields:Field[]=[{key:'display_name',label:'显示名称',required:true}];if(user.id!==auth.user?.id){fields.push({key:'role',label:'角色',type:'select',options:roleOptions,required:true},{key:'status',label:'账号状态',type:'select',options:[{value:'active',label:'启用'},{value:'inactive',label:'停用'}]})}editor.open('编辑用户',fields,user,'/users/'+user.id,'PATCH')}
function modelSettings() {editor.open('模型与任务设置',[{key:'ai_mode',label:'生成模式',type:'select',required:true,options:[{value:'demo',label:'演示规则 / 示意素材'},{value:'compatible',label:'真实模型服务'}]},{key:'job_timeout_seconds',label:'任务超时时间（秒）',type:'number',min:5,max:3600,step:1},{key:'job_max_attempts',label:'每个任务最大尝试次数',type:'number',min:1,max:10,step:1}],settings.value!,'/workspace/settings','PATCH')}
onMounted(load)
</script>
<template>
  <div class="page-heading"><div><span class="eyebrow">WORKSPACE SETTINGS</span><h1>系统设置<span class="heading-dot">.</span></h1><p>给团队合适的权限，为工作台配置合适的能力。</p></div></div>
  <div v-if="error" class="error-panel">{{ error }}<button @click="load">重试</button></div>
  <template v-if="settings"><div class="detail-columns"><section class="panel"><div class="panel-heading"><div><h2><Cpu :size="18" />模型与任务</h2><p>密钥由后端环境变量管理，页面不显示密钥。</p></div><button class="button secondary small-button" @click="modelSettings"><Pencil :size="14" />编辑配置</button></div><dl class="settings-list"><div><dt>当前生成模式</dt><dd class="text-success">{{ settings.ai_mode==='demo'?'演示模式':'真实模型模式' }}</dd></div><div><dt>文本模型</dt><dd>{{ settings.text_model_configured?settings.ai_text_model:'未配置' }}</dd></div><div><dt>图片模型</dt><dd>{{ settings.image_model_configured?settings.ai_image_model:'未配置' }}</dd></div><div><dt>视频服务</dt><dd>{{ settings.video_model_configured?'已配置适配服务':'未配置' }}</dd></div><div><dt>任务执行器</dt><dd>{{ settings.worker_enabled?'已启用':'已关闭（使用独立执行器）' }}</dd></div><div><dt>超时时间 / 最大尝试次数</dt><dd>{{ settings.job_timeout_seconds }} 秒 / {{ settings.job_max_attempts }} 次</dd></div></dl><div class="panel-body border-top small muted">需要真实模型时，在 backend/.env 中设置 AI_BASE_URL、AI_API_KEY、AI_TEXT_MODEL、AI_IMAGE_MODEL 后重启后端。视频适配协议见项目说明。</div></section>
  <section class="panel"><div class="panel-heading"><div><h2><SlidersHorizontal :size="18" />工作区工具</h2><p>演示初始化与手动调度入口</p></div></div><div class="settings-tools"><div><span class="tool-icon sage"><Sparkles :size="21" /></span><div><h3>初始化演示数据</h3><p>创建完整单品运营示例，重复执行保留已有修改。</p></div><button class="button secondary small-button" :disabled="!!action.busy || !settings.demo_enabled" @click="action.run('demo',()=>api('/workspace/demo-data','POST'),'演示数据已准备完成')">{{ action.busy==='demo'?'准备中…':'初始化' }}</button></div><div><span class="tool-icon sand"><RefreshCw :size="21" /></span><div><h3>执行到期竞品监控</h3><p>每次最多检查 20 个公开页面；失败原因写入快照。</p></div><button class="button secondary small-button" :disabled="!!action.busy" @click="action.run('monitors',async()=>{monitorResult=await api('/workspace/competitor-monitors/run-due','POST')},'到期监控已执行')">{{ action.busy==='monitors'?'执行中…':'运行' }}</button></div><p v-if="monitorResult" class="callout small">本次运行 {{ monitorResult.run_count }} 个监控，具体结果可在商品的竞品卡片查看。</p><div><span class="tool-icon blue"><RefreshCw :size="21" /></span><div><h3>扫描超时任务</h3><p>内置执行器会自动检查，也可在此手动运行。</p></div><button class="button secondary small-button" :disabled="!!action.busy" @click="action.run('sweep',()=>api('/workspace/generation-jobs/sweep-timeouts','POST'),'超时任务已扫描')">扫描</button></div></div></section></div>
  <section class="panel section-block"><div class="panel-heading"><div><h2><Users :size="18" />团队用户<span class="count-pill">{{ users.length }}</span></h2><p>管理员管理团队；运营人员处理业务；查看人员只读。</p></div><button class="button primary small-button" @click="createUser"><Plus :size="15" />创建用户</button></div><div class="table-wrap"><table><thead><tr><th>用户</th><th>角色</th><th>状态</th><th>最近登录</th><th>操作</th></tr></thead><tbody><tr v-for="user in users" :key="user.id"><td><div class="product-cell"><span class="user-avatar">{{ user.display_name.slice(0,1) }}</span><div><strong>{{ user.display_name }} <small v-if="user.id===auth.user?.id" class="muted">（我）</small></strong><small>{{ user.username }}</small></div></div></td><td>{{ labels[user.role] }}</td><td><StatusBadge :value="user.status" :label="user.status==='active'?'启用':'停用'" /></td><td class="muted">{{ time(user.last_login_at) }}</td><td><div class="inline-actions"><button class="text-button" @click="editUser(user)"><Pencil :size="13" />编辑</button><button class="text-button" @click="editor.open('重设密码 · '+user.username,[{key:'password',label:'新密码',type:'password',required:true,hint:'至少 8 位；保存后该用户的现有登录会话将失效。'}],{},'/users/'+user.id,'PATCH')"><KeyRound :size="13" />重设密码</button></div></td></tr></tbody></table></div></section>
  <section class="permission-cards"><article><ShieldCheck :size="21" /><h3>管理员</h3><p>管理用户、店铺与账号配置，处理全部业务和投放确认。</p></article><article><Users :size="21" /><h3>运营人员</h3><p>维护商品、竞品、素材与经营数据，确认建议并更新实验。</p></article><article><Users :size="21" /><h3>查看人员</h3><p>查看工作台、商品、诊断与报告，不执行写入和确认操作。</p></article></section></template>
  <FormModal v-if="editor.form" v-bind="editor.form" :saving="editor.saving" :error="editor.error" @close="editor.close" @submit="editor.save" />
</template>
